<?php get_header();$term=mb_substr(sanitize_text_field(get_search_query()),0,100);global $wpdb;if($term)$wpdb->insert($wpdb->prefix.'pt_searches',['query'=>$term,'created'=>current_time('mysql')]);$page=max(1,absint($_GET['pg']??1));$types=['product','page','post','pt_service','pt_industry','pt_project','pt_faq'];$args=['post_type'=>$types,'post_status'=>'publish','posts_per_page'=>9,'paged'=>$page,'s'=>$term,'pt_search'=>true,'meta_query'=>pt_sample_query()];$results=new WP_Query($args);$fuzzy=false;if(!$results->found_posts&&strlen($term)>=3&&strpos($term,' ')===false){$candidates=$wpdb->get_results("SELECT ID,post_title FROM {$wpdb->posts} WHERE post_status='publish' AND post_type IN ('product','pt_service','pt_industry') LIMIT 10000");$ids=[];foreach($candidates as $p)foreach(preg_split('/[\s\-]+/',strtolower($p->post_title)) as $word)if(strlen($word)>2&&levenshtein(strtolower($term),$word)<=1){$ids[]=$p->ID;break;}if($ids){$fuzzy=true;$results=new WP_Query(['post_type'=>$types,'post_status'=>'publish','post__in'=>$ids,'posts_per_page'=>9,'paged'=>$page,'meta_query'=>pt_sample_query()]);}} ?>
<section><div class="wrap"><span class="eyebrow">SEARCH PANDATEC</span><h1>Search results</h1><form class="search-form" action="<?php echo esc_url(home_url('/')); ?>"><label for="results-search">Product, SKU or topic</label><input id="results-search" type="search" name="s" value="<?php echo esc_attr($term); ?>" required><button class="btn">Search</button></form>
<?php if($fuzzy)echo '<p>Showing close matches for “'.esc_html($term).'”.</p>';if($results->posts){echo '<p>'.(int)$results->found_posts.' results</p><div class="content-grid">';foreach($results->posts as $p){$url=$p->post_type==='pt_faq'?home_url('/faq/'):get_permalink($p);echo '<article><span class="eyebrow">'.esc_html(get_post_type_object($p->post_type)->labels->singular_name).'</span><h2><a href="'.esc_url($url).'">'.esc_html($p->post_title).'</a></h2><p>'.esc_html(wp_trim_words(wp_strip_all_tags(str_replace('</p>','</p> ',$p->post_content)),25)).'</p></article>';}echo '</div><nav class="pagination" aria-label="Search result pages">'.paginate_links(['base'=>add_query_arg('pg','%#%'),'current'=>$page,'total'=>$results->max_num_pages]).'</nav>';}else echo '<div class="empty-state"><h2>No matches yet</h2><p>Try a broader product term, a SKU, or describe your requirements in an enquiry.</p><a class="btn" href="'.esc_url(home_url('/request-a-quote/')).'">Request a Quote</a></div>'; ?></div></section><?php get_footer(); ?>
